const tasks = [
  { name: 'Clean the windows', energy: 'High', minutes: 15 },
  { name: 'Deep scrub the shower & toilet', energy: 'High', minutes: 15 },
  { name: 'Mop the kitchen & living room floors', energy: 'High', minutes: 12 },
  { name: 'Vacuum the living and master bedroom carpets', energy: 'High', minutes: 12 },
  { name: 'Wipe down kitchen counters & induction stove', energy: 'Low', minutes: 5 },
  { name: 'Clean office', energy: 'Medium', minutes: 10 },
  { name: 'Empty all trash bins & take out recycling', energy: 'Low', minutes: 4 },
  { name: 'Dust the TV console and coffee table', energy: 'Low', minutes: 5 },
  { name: 'Wipe down bathroom mirror and sink', energy: 'Low', minutes: 4 },
  { name: 'Load and start the laundry machine', energy: 'Low', minutes: 6 }
];
const now = new Date();
const dayOfWeek = now.toLocaleDateString('en-US', { weekday: 'long' });
const dateStr = now.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
return [{ json: { dayOfWeek, date: dateStr, tasks } }];

