={{ (() => {
const plan = JSON.parse($('AI Chore Allocator').item.json.output);
const day = $('Master Task List').item.json.dayOfWeek;
const date = $('Master Task List').item.json.date;
const lines = plan.selected.map((t, i) => (i + 1) + '. ' + t.name + ' — ~' + t.minutes + ' min (' + t.energy + ' energy)').join('\n');
return 'Good morning! Here are your micro-chores for ' + day + ', ' + date + ':\n\n' + lines + '\n\nTotal: ~' + plan.totalMinutes + ' minutes.\n' + plan.reasoning;
})() }}
